function Resolve-CacheEntry($dll, $expected) {
  foreach ($f in (Get-ChildItem $cacheDir -File -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -like ($dll + "*.bin") })) {
    if ((Get-FileHash -LiteralPath $f.FullName).Hash -eq $expected) { return $f.FullName }
  }
  return $null
}
$copied = 0; $ok = 0
foreach ($e in $pool) {
  $dst = Join-Path $TestBinDir $e[0]
  $cur = $null
  if (Test-Path -LiteralPath $dst) { $cur = (Get-FileHash -LiteralPath $dst).Hash }
  if ($cur -eq $e[1]) { $ok++; continue }
  $kind = $e[2].Split(":")[0]
  $what = $e[2].Substring($kind.Length + 1)
  $srcPath = $null
  if ($kind -eq "cache") { $srcPath = Join-Path $cacheDir $what }
  elseif ($kind -eq "closure") { $srcPath = Join-Path $closureDir $what }
  elseif ($kind -eq "hostinputs") { $srcPath = Join-Path $hostDir $what }
  elseif ($kind -eq "bin") { $srcPath = Join-Path $origBinDir $what }
  else { throw ("Unknown pool source kind: " + $e[2]) }
  if (($null -eq $srcPath) -or (!(Test-Path -LiteralPath $srcPath))) {
    if ($kind -eq "cache") { $srcPath = Resolve-CacheEntry $e[0] $e[1] }
  }
  if (($null -eq $srcPath) -or (!(Test-Path -LiteralPath $srcPath))) { throw ("Pool source missing: " + $e[2]) }
  Copy-Item -LiteralPath $srcPath -Destination $dst -Force
  $got = (Get-FileHash -LiteralPath $dst).Hash
  if ($got -ne $e[1]) { throw ("Hash mismatch after copy: " + $e[0]) }
  $copied++
}
Write-Output ("pool-seed: verified=" + $ok + " copied=" + $copied + " total=" + $pool.Count)
